INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47761, 'Job 14:12', 'Job', 14, 12, 'نو انسان په قبر کښې څملى او بيا نۀ راپاڅى، چې ترڅو پورې آسمانونه ختم شوى نۀ وى، نو هغوئ به د خپل خوب نه نۀ راپاڅى.', 'نو انسان په قبر کشې چملی او بیا نۀ راپاچی، چې ترچو پورې اسمانونه ختم شوی نۀ وی، نو هغوی به د خپل خوب نه نۀ راپاچی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47762, 'Job 14:13', 'Job', 14, 13, 'کاش، چې تا زۀ په قبر کښې پټ کړے وے، او چې تر هغې پورې دې زۀ فنا کړے وے چې ستا غصه تېره شوے وے، او يا دې يو وخت مقرر کړے وے چې زۀ دې راپه ياد شوے وے.', 'کاش، چې تا زۀ په قبر کشې پت کرے وے، او چې تر هغې پورې دې زۀ فنا کرے وے چې ستا غصه تېره شوے وے، او یا دې یو وخت مقرر کرے وے چې زۀ دې راپه یاد شوے وے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47763, 'Job 14:14', 'Job', 14, 14, 'چې انسان ختم شى، نو هغه بيا ژوندے کېدے شى څۀ؟ زۀ به زما د سخت محنت په دې ټولو ورځو کښې اِنتظار کوم تر هغې پورې چې زما تکليف ختم شى.', 'چې انسان ختم شی، نو هغه بیا ژوندے کېدے شی چۀ؟ زۀ به زما د سخت محنت په دې تولو ورجو کشې انتظار کوم تر هغې پورې چې زما تکلیف ختم شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47764, 'Job 14:15', 'Job', 14, 15, 'تۀ به ما ته آواز وکړې او زۀ به جواب درکړم، تۀ به د هغه مخلوق ارمان وکړې چې تا پېدا کړى دى.', 'تۀ به ما ته اواز وکرې او زۀ به جواب درکرم، تۀ به د هغه مخلوق ارمان وکرې چې تا پېدا کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47765, 'Job 14:16', 'Job', 14, 16, 'بيا به تۀ زما په هر قدم باندې نظر ساتې، خو زما د ګناهونو حساب به نۀ کوې.', 'بیا به تۀ زما په هر قدم باندې نظر ساتې، خو زما د ګناهونو حساب به نۀ کوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47766, 'Job 14:17', 'Job', 14, 17, 'زما ګناهونه به په يوه بوجۍ کښې بند شوې وى، او تۀ به زما ټولې غلطيانې پټې کړې.', 'زما ګناهونه به په یوه بوجی کشې بند شوې وی، او تۀ به زما تولې غلطیانې پتې کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47767, 'Job 14:18', 'Job', 14, 18, 'خو غر راوغورزيږى او ټوټې ټوټې شى، او غټ غټ کاڼى د خپل ځائ نه وخوځيږى،', 'خو غر راوغورزیزی او توتې توتې شی، او غت غت کانی د خپل جای نه وخوجیزی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47768, 'Job 14:19', 'Job', 14, 19, 'اوبۀ کاڼى مږى، او سېلاب د زمکې خاوره اوړى، نو داسې تۀ د انسان اُميد تباه کوې.', 'اوبۀ کانی مزی، او سېلاب د زمکې خاوره اوری، نو داسې تۀ د انسان امید تباه کوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47769, 'Job 14:20', 'Job', 14, 20, 'تۀ په هغوئ باندې تل غالب يې او هغوئ ختميږى، تۀ د هغوئ شکلونه بدلوې او د مرګ په طرف يې بوځې.', 'تۀ په هغوی باندې تل غالب یې او هغوی ختمیزی، تۀ د هغوی شکلونه بدلوې او د مرګ په طرف یې بوجې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47770, 'Job 14:21', 'Job', 14, 21, 'کۀ د هغۀ بچو ته عزت مِلاو شى، نو هغۀ ته پته نۀ لګى، او کۀ د هغۀ د بچو سپکاوے وشى نو هم هغۀ ته پته نۀ لګى.', 'کۀ د هغۀ بچو ته عزت ملاو شی، نو هغۀ ته پته نۀ لګی، او کۀ د هغۀ د بچو سپکاوے وشی نو هم هغۀ ته پته نۀ لګی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47771, 'Job 14:22', 'Job', 14, 22, 'هغۀ ته صِرف د خپل بدن درد محسوسيږى، او هغه صرف په خپل غم کښې آخته وى.“', 'هغۀ ته صرف د خپل بدن درد محسوسیزی، او هغه صرف په خپل غم کشې اخته وی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_14_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47772, 'Genesis 11:1', 'Genesis', 11, 1, 'په هغه وخت کې د ټولې نړۍ خلکو یوه ژبه درلودله او یو قسم خبرې به یې کولې.', 'په هغه وخت کې د تولې نری خلکو یوه ژبه درلودله او یو قسم خبرې به یې کولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47773, 'Genesis 11:2', 'Genesis', 11, 2, 'خو وروسته هغوی د ختیځ خواته کډه وکړه او د شنعار په ځمکه کې یې یو هوار ځای پیدا کړ او هلته اوسېدل.', 'خو وروسته هغوی د ختیج خواته کده وکره او د شنعار په جمکه کې یې یو هوار جای پیدا کر او هلته اوسېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47774, 'Genesis 11:3', 'Genesis', 11, 3, 'هغوی یو بل ته وویل: «راځئ چې خښتې جوړې کړو او هغه ښې پخې کړو.» هغوی د تیږو په ځای خښتې او د مسالې په ځای د قیر نه کار واخیست.', 'هغوی یو بل ته وویل: «راجی چې خشتې جورې کرو او هغه شې پخې کرو.» هغوی د تیزو په جای خشتې او د مسالې په جای د قیر نه کار واخیست.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47775, 'Genesis 11:4', 'Genesis', 11, 4, 'هغوی وویل: «راځئ چې د خپل ځان دپاره یو ښار ودان کړو او په هغه کې یو لوړ برج جوړ کړو چې سر یې اسمان ته ورسیږي، ترڅو د خپل ځان دپاره یو نوم وګټو، داسې نه شي چې په ټوله دنیا کې خپاره شو.»', 'هغوی وویل: «راجی چې د خپل جان دپاره یو شار ودان کرو او په هغه کې یو لور برج جور کرو چې سر یې اسمان ته ورسیزی، ترچو د خپل جان دپاره یو نوم وګتو، داسې نه شی چې په توله دنیا کې خپاره شو.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47776, 'Genesis 11:5', 'Genesis', 11, 5, 'خو کله چې څښتن راښکته شو چې هغه ښار او برج چې خلکو جوړ کړی ؤ وګوري،', 'خو کله چې چشتن راشکته شو چې هغه شار او برج چې خلکو جور کری و وګوری،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47777, 'Genesis 11:6', 'Genesis', 11, 6, 'هغه وویل: «اوس هغوی یو قوم دی او په یوه ژبه خبرې کوي. دا یوازې د کار پیل دی. هغوی به ډېر زر د دې توان پیدا کړي چې هرڅه وغواړي هغه به سرته ورسوي.', 'هغه وویل: «اوس هغوی یو قوم دی او په یوه ژبه خبرې کوی. دا یوازې د کار پیل دی. هغوی به دېر زر د دې توان پیدا کری چې هرچه وغواری هغه به سرته ورسوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47778, 'Genesis 11:7', 'Genesis', 11, 7, 'راځئ چې ښکته شو او د هغوی ژبه سره ګډه وډه کړو، ترڅو دوی یو د بل په خبرو باندې پوه نه شي.»', 'راجی چې شکته شو او د هغوی ژبه سره ګده وده کرو، ترچو دوی یو د بل په خبرو باندې پوه نه شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47779, 'Genesis 11:8', 'Genesis', 11, 8, 'نو څښتن هغوی په ټوله دنیا کې خپاره کړل او هغوی مجبور شول چې د ښار د جوړولو څخه لاس واخلي.', 'نو چشتن هغوی په توله دنیا کې خپاره کرل او هغوی مجبور شول چې د شار د جورولو چخه لاس واخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47780, 'Genesis 11:9', 'Genesis', 11, 9, 'په دې سبب هغه ځای د بابل په نوم یاد شو، ځکه چې څښتن هلته د هغوی ژبه ګډه وډه کړه او هغوی یې په ټوله دنیا کې خپاره کړل.', 'په دې سبب هغه جای د بابل په نوم یاد شو، جکه چې چشتن هلته د هغوی ژبه ګده وده کره او هغوی یې په توله دنیا کې خپاره کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47781, 'Genesis 11:10', 'Genesis', 11, 10, 'دا د سام اولاده ده: د سېلاب څخه دوه کاله وروسته هغه وخت چې سام د سلو کالو په عمر ؤ، د هغه زوی ارفکشاد پیدا شو.', 'دا د سام اولاده ده: د سېلاب چخه دوه کاله وروسته هغه وخت چې سام د سلو کالو په عمر و، د هغه زوی ارفکشاد پیدا شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47782, 'Genesis 11:11', 'Genesis', 11, 11, 'د آرفکشاد د پیدا کېدلو څخه وروسته سام پنځه سوه کاله نور هم ژوند وکړ او نور اولادونه یې پیدا شول.', 'د ارفکشاد د پیدا کېدلو چخه وروسته سام پنجه سوه کاله نور هم ژوند وکر او نور اولادونه یې پیدا شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47783, 'Genesis 11:12', 'Genesis', 11, 12, 'ارفکشاد د پنځه دېرشو کالو په عمر ؤ چې د هغه زوی شالح پیدا شو.', 'ارفکشاد د پنجه دېرشو کالو په عمر و چې د هغه زوی شالح پیدا شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47784, 'Genesis 11:13', 'Genesis', 11, 13, 'د شالح د پیدا کېدلو څخه وروسته ارفکشاد څلور سوه درې کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', 'د شالح د پیدا کېدلو چخه وروسته ارفکشاد چلور سوه درې کاله نور هم ژوند وکر او نور زامن او لورګانې یې پیدا شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47785, 'Genesis 11:14', 'Genesis', 11, 14, 'هغه وخت چې شالح د دېرشو کالو په عمر ؤ د هغه زوی عیبر پیدا شو.', 'هغه وخت چې شالح د دېرشو کالو په عمر و د هغه زوی عیبر پیدا شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47786, 'Genesis 11:15', 'Genesis', 11, 15, 'له هغې وروسته، شالح څلور سوه درې کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', 'له هغې وروسته، شالح چلور سوه درې کاله نور هم ژوند وکر او نور زامن او لورګانې یې پیدا شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47787, 'Genesis 11:16', 'Genesis', 11, 16, 'عیبر د څلوردېرشو کالو په عمر ؤ چې د هغه زوی فالج پیدا شو.', 'عیبر د چلوردېرشو کالو په عمر و چې د هغه زوی فالج پیدا شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47788, 'Genesis 11:17', 'Genesis', 11, 17, 'کله چې فالج پیدا شو، عیبر څلور سوه دېرش کاله نور هم ژوند وکړ او زامن او لورګانې یې پیدا شوې.', 'کله چې فالج پیدا شو، عیبر چلور سوه دېرش کاله نور هم ژوند وکر او زامن او لورګانې یې پیدا شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_11_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
