(47804, 'Ruth 1:3', 'Ruth', 1, 3, 'الیملک مړ شو او نعومي د خپلو دوو زامنو سره یوازې پاتې شوه.', 'الیملک مر شو او نعومی د خپلو دوو زامنو سره یوازې پاتې شوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47805, 'Ruth 1:4', 'Ruth', 1, 4, 'وروسته د نعومي زامنو موآبي ښځې وکړې. د یوې نوم عرفه او د بلې نوم روت ؤ. وروسته له هغې چې هغوی هلته نژدې لس کاله اوسېدل،', 'وروسته د نعومی زامنو موابی شجې وکرې. د یوې نوم عرفه او د بلې نوم روت و. وروسته له هغې چې هغوی هلته نژدې لس کاله اوسېدل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47806, 'Ruth 1:5', 'Ruth', 1, 5, 'محلون او کیلون هم مړه شول. نو اوس نعومي مېړه او زامن دواړه نه درلودل.', 'محلون او کیلون هم مره شول. نو اوس نعومی مېره او زامن دواره نه درلودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47807, 'Ruth 1:8', 'Ruth', 1, 8, 'نعومي خپلو دواړو انږورګانو ته وویل: «ځئ هره یوه د خپلو میندو کورونو ته لاړې شئ، زما څښتن دې په تاسو مهربانه شي لکه څنګه چې تاسو په ما او زما په مړو زامنو باندې مهرباني وکړه.', 'نعومی خپلو دوارو انزورګانو ته وویل: «جی هره یوه د خپلو میندو کورونو ته لارې شی، زما چشتن دې په تاسو مهربانه شی لکه چنګه چې تاسو په ما او زما په مرو زامنو باندې مهربانی وکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47808, 'Ruth 1:9', 'Ruth', 1, 9, 'خدای دې تاسو هرې یوې ته بل مېړه او کور درکړي.» نعومي دوی ښکل کړې. هغوی په لوړ اواز سره وژړل', 'خدای دې تاسو هرې یوې ته بل مېره او کور درکری.» نعومی دوی شکل کرې. هغوی په لور اواز سره وژرل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47809, 'Ruth 1:10', 'Ruth', 1, 10, 'او ویې ویل: «نه، مونږ غواړو چې ستا سره لاړې شو او ستا د خلکو په منځ کې واوسو.»', 'او ویې ویل: «نه، مونز غوارو چې ستا سره لارې شو او ستا د خلکو په منج کې واوسو.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47810, 'Ruth 1:11', 'Ruth', 1, 11, 'خو نعومي په ځواب کې وویل: «زما لورګانو، تاسو ولې خپلو کورونو ته نه ستنېږئ؟ زما سره ستاسو تګ تاسو ته څه ګټه رسوي؟ تاسو فکر کوئ چې زه به نور زامن راوړم، ترڅو د هغوی سره تاسو ودونه وکړئ؟', 'خو نعومی په جواب کې وویل: «زما لورګانو، تاسو ولې خپلو کورونو ته نه ستنېزی؟ زما سره ستاسو تګ تاسو ته چه ګته رسوی؟ تاسو فکر کوی چې زه به نور زامن راورم، ترچو د هغوی سره تاسو ودونه وکری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47811, 'Ruth 1:12', 'Ruth', 1, 12, 'بېرته کور ته لاړې شئ زما لورګانو، ځکه چې زه ډېره زړه یم او بیا د واده کولو وړ نه یم. حتی که چېرې زه نن شپه هم واده شم او زامن وزېږوم،', 'بېرته کور ته لارې شی زما لورګانو، جکه چې زه دېره زره یم او بیا د واده کولو ور نه یم. حتی که چېرې زه نن شپه هم واده شم او زامن وزېزوم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47812, 'Ruth 1:13', 'Ruth', 1, 13, 'نو ایا تاسو به هغوی ته صبر وکړئ چې هغوی ځلمیان شي او تاسو سره واده وکړي؟ نه، زما لورګانو! ژوند زما دپاره ستاسو په پرتله ډېر سخت دی، ځکه چې څښتن اوس په ما دا سخته راوستې ده.»', 'نو ایا تاسو به هغوی ته صبر وکری چې هغوی جلمیان شی او تاسو سره واده وکری؟ نه، زما لورګانو! ژوند زما دپاره ستاسو په پرتله دېر سخت دی، جکه چې چشتن اوس په ما دا سخته راوستې ده.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47813, 'Ruth 1:14', 'Ruth', 1, 14, 'دوی بیا وژړل او عرفې خپله خواښې د خدای پامانۍ په وخت کې ښکل کړه، خو روت د هغې لمن پرېنښودله.', 'دوی بیا وژرل او عرفې خپله خواشې د خدای پامانی په وخت کې شکل کره، خو روت د هغې لمن پرېنشودله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47814, 'Ruth 1:15', 'Ruth', 1, 15, 'نعومي بیا روت ته وویل: «ګوره ستا یور بېرته خپلو خلکو او خپل خدای ته ځي! ته ولې هغې سره نه ځې؟»', 'نعومی بیا روت ته وویل: «ګوره ستا یور بېرته خپلو خلکو او خپل خدای ته جی! ته ولې هغې سره نه جې؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47815, 'Ruth 1:16', 'Ruth', 1, 16, 'روت په ځواب کې وویل: «ماته مه وایه چې تا پرېږدم او کور ته ستنه شم! زه به هلته ځم چېرته چې ته ځې او زه به هلته اوسېږم چېرته چې ته اوسېږې. ستا خلک به زما خلک وي او ستا خدای به زما خدای وي.', 'روت په جواب کې وویل: «ماته مه وایه چې تا پرېزدم او کور ته ستنه شم! زه به هلته جم چېرته چې ته جې او زه به هلته اوسېزم چېرته چې ته اوسېزې. ستا خلک به زما خلک وی او ستا خدای به زما خدای وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47816, 'Ruth 1:17', 'Ruth', 1, 17, 'زه به هلته مړه کېږم چېرته چې ته مړه کېږې او هلته به ښخېږم. څښتن دې ماته د ټولو نه درنده سزا راکړي که چېرې د مرګ نه پرته سره بېل شو.»', 'زه به هلته مره کېزم چېرته چې ته مره کېزې او هلته به شخېزم. چشتن دې ماته د تولو نه درنده سزا راکری که چېرې د مرګ نه پرته سره بېل شو.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47817, 'Ruth 1:18', 'Ruth', 1, 18, 'کله چې نعومي ولیدل چې روت کلکه اراده کړې چې د هغې سره لاړه شي، نو نعومي هغه نوره مجبوره نه کړه چې بېرته موآب ته لاړه شي.', 'کله چې نعومی ولیدل چې روت کلکه اراده کرې چې د هغې سره لاره شی، نو نعومی هغه نوره مجبوره نه کره چې بېرته مواب ته لاره شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47818, 'Ruth 1:19', 'Ruth', 1, 19, 'هغوی دواړه بیت لحم ته ورسېدلې او د ټول ښار خلک خوشحاله شول او ښځو د یو بل څخه وپوښتل: «ایا دا په رښتیا نعومي ده؟»', 'هغوی دواره بیت لحم ته ورسېدلې او د تول شار خلک خوشحاله شول او شجو د یو بل چخه وپوشتل: «ایا دا په رشتیا نعومی ده؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47819, 'Ruth 1:20', 'Ruth', 1, 20, 'بیا هغې دوی ته وویل: «له دې وروسته ما نعومي مه بولئ! ما ماره بولئ، ځکه چې مطلق قادر خدای زما ژوند تریخ کړی دی.', 'بیا هغې دوی ته وویل: «له دې وروسته ما نعومی مه بولی! ما ماره بولی، جکه چې مطلق قادر خدای زما ژوند تریخ کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47820, 'Ruth 1:21', 'Ruth', 1, 21, 'کله چې زه لاړم نو ما هرڅه درلودل، خو څښتن زه بېرته تش لاس راوستلې یم. څنګه تاسو کولای شئ بیاهم ما نعومي وبولئ؟ اوس مطلق قادر څښتن زما په ضد شوی دی او زما ژوند یې ډېر سخت کړی دی.»', 'کله چې زه لارم نو ما هرچه درلودل، خو چشتن زه بېرته تش لاس راوستلې یم. چنګه تاسو کولای شی بیاهم ما نعومی وبولی؟ اوس مطلق قادر چشتن زما په ضد شوی دی او زما ژوند یې دېر سخت کری دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_1_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47821, 'Ruth 1:22', 'Ruth', 1, 22, 'نو په دې ډول نعومي د خپلې موآبي انږور سره د موآب څخه بېرته راغله. دوی په داسې حال کې بیت لحم ته راورسېدلې چې د اوربشو لو په پیل کېدلو ؤ.', 'نو په دې دول نعومی د خپلې موابی انزور سره د مواب چخه بېرته راغله. دوی په داسې حال کې بیت لحم ته راورسېدلې چې د اوربشو لو په پیل کېدلو و.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47822, 'Genesis 26:1', 'Genesis', 26, 1, 'په هغه وطن کې برسېره په هغې قحطۍ باندې چې پخوا د ابراهیم په وخت کې راغلې وه، بله قحطي هم راغله. اسحاق د فلسطینیانو پاچا ابي‌ملک ته چې په جرار کې ؤ، ورغی.', 'په هغه وطن کې برسېره په هغې قحطی باندې چې پخوا د ابراهیم په وخت کې راغلې وه، بله قحطی هم راغله. اسحاق د فلسطینیانو پاچا ابی‌ملک ته چې په جرار کې و، ورغی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47823, 'Genesis 26:2', 'Genesis', 26, 2, 'څښتن اسحاق ته ښکاره شو او ویې ویل: «مصر ته مه ځه. په همدې وطن کې په هغه ځای کې چې زه یې درته وایم، اوسېږه.', 'چشتن اسحاق ته شکاره شو او ویې ویل: «مصر ته مه جه. په همدې وطن کې په هغه جای کې چې زه یې درته وایم، اوسېزه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47824, 'Genesis 26:3', 'Genesis', 26, 3, 'همدلته اوسېږه. زه به ستا سره مل یم او برکت به درکړم. زه به تا او ستا اولادې ته دا ټوله سیمه درکړم او په هغې وعدې باندې به ټینګ ولاړ یم چې ستا د پلار ابراهیم سره مې کړې وه.', 'همدلته اوسېزه. زه به ستا سره مل یم او برکت به درکرم. زه به تا او ستا اولادې ته دا توله سیمه درکرم او په هغې وعدې باندې به تینګ ولار یم چې ستا د پلار ابراهیم سره مې کرې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47825, 'Genesis 26:4', 'Genesis', 26, 4, 'ستا اولاده به د اسمان د ستورو په شان زیاته کړم او هغوی ته به دا ټوله سیمه ورکړم. ستا د اولادې په وسیله به د ځمکې په مخ ټول قومونه برکت ومومي،', 'ستا اولاده به د اسمان د ستورو په شان زیاته کرم او هغوی ته به دا توله سیمه ورکرم. ستا د اولادې په وسیله به د جمکې په مخ تول قومونه برکت ومومی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47826, 'Genesis 26:5', 'Genesis', 26, 5, 'ځکه چې ابراهیم زما اطاعت کړی دی او زما په ټولو حکمونو او قوانینو باندې یې عمل کړی دی.»', 'جکه چې ابراهیم زما اطاعت کری دی او زما په تولو حکمونو او قوانینو باندې یې عمل کری دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47827, 'Genesis 26:6', 'Genesis', 26, 6, 'نو اسحاق په جرار کې پاتې شو.', 'نو اسحاق په جرار کې پاتې شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47828, 'Genesis 26:7', 'Genesis', 26, 7, 'کله چې د هغه ځای خلکو د اسحاق څخه د ربکا په اړه پوښتنه وکړه، هغه وویل: «هغه زما خور ده.» ځکه هغه وېرېده چې داسې ووایي چې هغه زما ښځه ده. هغه فکر کاوه چې د هغه ځای خلک به هغه د ربکا په خاطر ووژني، ځکه چې هغه ډېره ښکلې وه.', 'کله چې د هغه جای خلکو د اسحاق چخه د ربکا په اره پوشتنه وکره، هغه وویل: «هغه زما خور ده.» جکه هغه وېرېده چې داسې ووایی چې هغه زما شجه ده. هغه فکر کاوه چې د هغه جای خلک به هغه د ربکا په خاطر ووژنی، جکه چې هغه دېره شکلې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47829, 'Genesis 26:8', 'Genesis', 26, 8, 'څرنګه چې اسحاق هلته زیات وخت تېر کړ، نو ابي‌ملک د فلسطینیانو پاچا د کړکۍ څخه لاندې وکتل او ویې لیدل چې اسحاق خپله ښځه ربکا په غېږ کې نیولې وه او هغه یې ښکلوله.', 'چرنګه چې اسحاق هلته زیات وخت تېر کر، نو ابی‌ملک د فلسطینیانو پاچا د کرکی چخه لاندې وکتل او ویې لیدل چې اسحاق خپله شجه ربکا په غېز کې نیولې وه او هغه یې شکلوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47830, 'Genesis 26:9', 'Genesis', 26, 9, 'نو ابي‌ملک اسحاق راوغوښت او ورته ویې ویل: «هغه په رښتیا سره ستا ښځه ده! نو ولې دې وویل چې هغه ستا خور ده؟» اسحاق ځواب ورکړ: «ما فکر وکړ چې کېدای شي د هغې په خاطر ووژل شم.»', 'نو ابی‌ملک اسحاق راوغوشت او ورته ویې ویل: «هغه په رشتیا سره ستا شجه ده! نو ولې دې وویل چې هغه ستا خور ده؟» اسحاق جواب ورکر: «ما فکر وکر چې کېدای شی د هغې په خاطر ووژل شم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47831, 'Genesis 26:10', 'Genesis', 26, 10, 'ابي‌ملک وویل: «تا زمونږ سره څه وکړل؟ کېدای شو چې زما د کسانو څخه کوم یو ستا د ښځې سره څملاستلی وای او مونږ به دې ګناهکار کړي وای.»', 'ابی‌ملک وویل: «تا زمونز سره چه وکرل؟ کېدای شو چې زما د کسانو چخه کوم یو ستا د شجې سره چملاستلی وای او مونز به دې ګناهکار کری وای.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47832, 'Genesis 26:11', 'Genesis', 26, 11, 'ابي‌ملک ټولو خلکو ته خبرداری ورکړ: «که هرڅوک د دې سړي یا دې ښځې سره بد چلند وکړي هغه به ووژل شي.»', 'ابی‌ملک تولو خلکو ته خبرداری ورکر: «که هرچوک د دې سری یا دې شجې سره بد چلند وکری هغه به ووژل شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_26_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
